SITE = make({'name': 'PoolServiceLasVegas.com', 'host': 'poolservicelasvegas.com', 'city': 'Las Vegas', 'area': 'the Las Vegas area', 'palette': {'sky': ['#2f6fb0', '#8cc3e3', '#f6d9a8', '#fbe9c6'], 'ground': ['#e6cfa3', '#c9ae7c'], 'far': '#b9937a'}, 'algae_when': 'Hot months and after dust storms', 'leaks_blurb': 'Desert heat evaporates a lot of water.', 'leaks_text': 'Pools in the desert can lose a lot of water to evaporation, especially in summer heat and wind, so a falling level is not always a leak. Set a bucket of pool water on an upper step, mark the water level inside the bucket and on the pool wall, and compare both after 24 hours with the pump off. If the pool dropped much more than the bucket, call a leak detection professional.', 'topic6': {'id': 'heat-scale', 'title': 'Heat, evaporation and scale', 'glyph': 'sun', 'blurb': 'Desert sun burns off chlorine and hard water leaves scale.', 'plate': [('Watch', 'Chlorine, water level, calcium'), ('Signs', 'White crust on tile, cloudy water'), ('Call a pro', 'Heavy scale or constant cloudiness')], 'text': 'Strong sun breaks down chlorine quickly, and a stabilizer (cyanuric acid) helps protect it. Evaporation concentrates minerals, and tap water in the Las Vegas area is typically hard, so calcium scale can form on tile and equipment. Testing calcium hardness and topping off carefully helps, and heavy scale is a professional cleaning job.', 'photo': 'white calcium scale line on the waterline tile of a desert backyard pool in strong sun'}, 'facts': [('About 300', 'Sunny days a year'), ('100°F and up', 'Common summer highs'), ('Hard water', 'Calcium scale is a regular problem'), ('Wind and dust', 'Add debris and cloudy water')], 'faq_often': 'Most Las Vegas pools get weekly service from spring through fall, when heat, sun, and dust are hardest on the water. In winter some owners drop to biweekly, as long as the pump keeps running and freeze protection is in place.', 'timing_lead': 'Las Vegas pools face intense sun, extreme heat, and dust. Here is what to watch for and when.', 'timing': [{'id': 'spring', 'title': 'Spring', 'glyph': 'leaf', 'when': 'March to May', 'text': 'Water warms quickly and wind brings dust and debris. Open and test the pool, clean the filter, and check the equipment before summer heat arrives.', 'facts': [('Watch for:', 'wind-blown debris, fast-warming water'), ('Do now:', 'clean the filter, test calcium and chlorine')], 'photo': 'a desert backyard pool in spring with palm trees and clear skies'}, {'id': 'summer', 'title': 'Summer', 'glyph': 'sun', 'when': 'June to September', 'text': 'Extreme heat burns off chlorine and evaporates water fast, and summer storms and dust can cloud the pool. Test often, keep stabilizer in range, top off water, and run the pump long enough each day.', 'facts': [('Watch for:', 'fast chlorine loss, evaporation, dust'), ('Do now:', 'test often, top off water, brush weekly')], 'photo': 'a bright desert backyard pool in intense summer sun with desert landscaping'}, {'id': 'fall', 'title': 'Fall', 'glyph': 'wind', 'when': 'October to November', 'text': 'Temperatures ease and the swim season stretches on. This is a good time to descale tile, service equipment, and tune chemistry for cooler water.', 'facts': [('Watch for:', 'scale buildup, shifting chemistry'), ('Do now:', 'service equipment, clean tile')], 'photo': 'a desert backyard pool at golden hour with mountains in the distance'}, {'id': 'winter', 'title': 'Winter', 'glyph': 'snow', 'when': 'December to February', 'text': 'Days are mild but nights can freeze. Keep the pump running on freezing nights, protect exposed pipes, and check the water level and chemistry every week or two.', 'facts': [('Watch for:', 'freezing nights, low water level'), ('Do now:', 'run the pump in freezing weather, check levels')], 'photo': 'a quiet desert backyard pool on a cool winter morning with distant mountains'}], 'license_ask': 'Ask whether the company holds any license Nevada requires for its work, and confirm it with the Nevada State Contractors Board.', 'hiring_callout': '<strong>Ask for proof.</strong> Request a certificate of insurance, ask whether the company holds any license Nevada requires for its work, and confirm it with the <a href="https://www.nvcontractorsboard.com" rel="noopener">Nevada State Contractors Board</a>.', 'quote_callout': '<strong>Need to check a license?</strong> Look up a company with the <a href="https://www.nvcontractorsboard.com" rel="noopener">Nevada State Contractors Board</a>.', 'zip_ph': 'e.g. Henderson or 89101', 'gov_html': 'the <a href="https://www.nvcontractorsboard.com" rel="noopener">Nevada State Contractors Board</a>, <a href="https://www.poolsafely.gov" rel="noopener">PoolSafely.gov</a>, and the <a href="https://www.cdc.gov/healthy-swimming/" rel="noopener">CDC</a>', 'footer_gov': 'For licensing, use the <a href="https://www.nvcontractorsboard.com" rel="noopener">Nevada State Contractors Board</a>.', 'official': [('Nevada State Contractors Board', 'https://www.nvcontractorsboard.com'), ('PoolSafely.gov (CPSC)', 'https://www.poolsafely.gov'), ('CDC: Healthy swimming', 'https://www.cdc.gov/healthy-swimming/'), ('Pool & Hot Tub Alliance', 'https://www.phta.org')], 'about_official': "Contractor licensing in Nevada is handled by the Nevada State Contractors Board. Pool safety guidance comes from PoolSafely.gov and the CDC's healthy swimming program.", 'hero_photo': 'a backyard swimming pool at a Las Vegas home with desert landscaping, palm trees, and red rock mountains in the distance'})
